import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingTransferToFront } from '../@mappers/hikingTransfers.mapper';
import {
  IHikingTransferCreateDTO,
  IHikingTransferDeleteDTO,
  IHikingTransferDTO,
  IHikingTransferMemberCreateDTO,
  IHikingTransferMemberDeleteDTO,
  IHikingTransferUpdateDTO,
} from '../@types/DTO/hikingTransfers.dto.types';
import { IHikingTransfer } from '../@types/hikingTransfers.types';

export const getHikingTransfers = async (id_hiking: number): Promise<IHikingTransfer[]> => {
  const res = await get('/ajax/hiking/transfers/transfer_list.php', { id_hiking }).then<
    IHikingTransferDTO[]
  >(handleApiError);
  return res.map(mapHikingTransferToFront);
};

export const addHikingTransfer = async (data: IHikingTransferCreateDTO): Promise<number> => {
  const res = await post('/ajax/hiking/transfers/transfer_add.php', data).then<{
    id: string;
  }>(handleApiError);
  return +res.id;
};

export const editHikingTransfer = async (data: IHikingTransferUpdateDTO): Promise<boolean> => {
  const res = await post('/ajax/hiking/transfers/transfer_edit.php', data).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};

export const deleteHikingTransfer = async (data: IHikingTransferDeleteDTO): Promise<boolean> => {
  const res = await post('/ajax/hiking/transfers/transfer_del.php', data).then<{ success: string }>(
    handleApiError,
  );
  return Boolean(res?.success);
};

export const addHikingTransferMember = async (
  data: IHikingTransferMemberCreateDTO,
): Promise<number> => {
  const res = await post('/ajax/hiking/transfers/transfer_member_add.php', data).then<{
    id: string;
  }>(handleApiError);
  return +res.id;
};

export const deleteHikingTransferMember = async (
  data: IHikingTransferMemberDeleteDTO,
): Promise<boolean> => {
  const res = await post('/ajax/hiking/transfers/transfer_member_del.php', data).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};
