import { getSQLDate } from '@helpers/dateHelper';

import {
  IHikingTransferCreateDTO,
  IHikingTransferDTO,
  IHikingTransferMemberDTO,
  IHikingTransferUpdateDTO,
} from '../@types/DTO/hikingTransfers.dto.types';
import { IHikingTransfer, IHikingTransferMember } from '../@types/hikingTransfers.types';

const mapHikingTransferMemberToFront = (
  backData: IHikingTransferMemberDTO,
): IHikingTransferMember => {
  return {
    id: +backData.id,
    user: {
      id: +backData.id_user,
      name: backData.name,
      surname: backData.surname,
      photo: backData.photo_50,
    },
    comment: backData.comment,
    created_at: new Date(backData.created_at),
    id_author: +backData.id_author,
  };
};

export const mapHikingTransferToFront = (backData: IHikingTransferDTO): IHikingTransfer => {
  return {
    id: +backData.id,
    comment: backData.comment,

    author: {
      id: +backData.id_author,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
    created_at: new Date(backData.created_at),
    schedule: backData.id_hiking_schedule
      ? {
          id: +backData.id_hiking_schedule,
          name: backData.schedule_name,
          description: backData.schedule_description,
          link: backData.schedule_link || null,

          start: new Date(backData.schedule_d1),
          finish: new Date(backData.schedule_d2),

          is_self_sufficiency: backData.schedule_is_self_sufficiency == '1',

          cost: null,

          foodAct: undefined,

          routeObject: undefined,

          article: null,
          currency: null,
        }
      : null,
    car: {
      name: backData.car_name,
      color: backData.car_color,
      photo: backData.car_photo,
      number: backData.car_number,
      capacity: +backData.car_capacity,
      capacity_max: backData.car_capacity_max ? +backData.car_capacity_max : null,
    },

    driver: {
      name: backData.driver_name,
      contacts: backData.driver_contacts,
      user: backData.driver_user_id
        ? {
            id: +backData.driver_user_id,
            name: backData.driver_user_name,
            surname: backData.driver_user_surname,
            photo: backData.driver_user_photo,
          }
        : null,
    },
    start: {
      date: new Date(backData.date_start),
      description: backData.start_description,
    },
    finish: {
      date: new Date(backData.date_finish),
      description: backData.finish_description,
    },

    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
    members: backData.members.map(mapHikingTransferMemberToFront),
  };
};

export const mapHikingTransferToAdd = (
  id_hiking: number,
  transfer: IHikingTransfer,
): IHikingTransferCreateDTO => {
  return {
    id_hiking,
    comment: transfer.comment,
    id_hiking_schedule: transfer.schedule?.id ?? null,
    driver_user_id: transfer.driver.user?.id ?? null,
    car_name: transfer.car.name,
    car_color: transfer.car.color,
    car_photo: transfer.car.photo,
    car_number: transfer.car.number,
    car_capacity: transfer.car.capacity,
    car_capacity_max: transfer.car.capacity ?? null,
    driver_name: transfer.driver.name,
    driver_contacts: transfer.driver.contacts,
    date_start: getSQLDate(transfer.start.date),
    date_finish: getSQLDate(transfer.finish.date),
    start_description: transfer.start.description,
    finish_description: transfer.finish.description,
  };
};

export const mapHikingTransferToUpdate = (
  id_hiking: number,
  transfer: IHikingTransfer,
): IHikingTransferUpdateDTO => {
  return {
    ...mapHikingTransferToAdd(id_hiking, transfer),
    id_hiking,
    id: transfer.id,
  };
};

export const getEmptyHikingTransferToFront = (
  d: Pick<IHikingTransfer, 'author'>,
  p: Partial<IHikingTransfer> = {},
): IHikingTransfer => {
  return {
    id: 0,
    comment: '',

    author: d.author,
    created_at: new Date(),
    schedule: null,
    car: {
      name: '',
      color: '',
      photo: '',
      number: '',
      capacity: 4,
      capacity_max: 5,
    },

    driver: {
      name: '',
      contacts: '',
      user: null,
    },
    start: {
      date: new Date(),
      description: '',
    },
    finish: {
      date: new Date(),
      description: '',
    },

    updated_at: null,
    members: [],
    ...p,
  };
};
